import { Table, StringColumn, IntegerColumn } from '../../db'

export const sys_security_operation = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    extends: 'sys_metadata',
    label: 'Operation',
    name: 'sys_security_operation',
    schema: {
        description: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Description',
            maxLength: 4000,
        }),
        order: IntegerColumn({
            label: 'Order',
        }),

        name: StringColumn({
            label: 'Name',
            mandatory: true,
            unique: true,
        }),
    },
    textIndex: true,
})
